1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * The single derived key that all owner duplicate detection is expressed through:
7	 * {@code <normalizedTelephone>|<email>|<householdId>}. The telephone is the normalized E.164 form,
8	 * the email is the lower-cased address (empty when absent) and the householdId is the shared
9	 * household identifier (empty when the owner belongs to no household). Two owners are duplicates
10	 * only when their whole identityKey is equal — because the telephone is part of the key, members of
11	 * the same household with different telephones have different keys and are both allowed.
12	 */
13	public final class OwnerIdentityKey {
14	
15	    private OwnerIdentityKey() {
16	    }
17	
18	    /** The identity key of a stored owner, from its telephone, email and householdId. */
19	    public static String of(Owner owner) {
20	        return of(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
21	    }
22	
23	    /** The identity key for the given normalized telephone, email and householdId. */
24	    public static String of(String telephone, String email, String householdId) {
25	        return safe(telephone) + "|" + safe(email) + "|" + safe(householdId);
26	    }
27	
28	    private static String safe(String value) {
29	        return value == null ? "" : value;
30	    }
31	}
