1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * The single duplicate check on {@code POST /api/owners}, keyed off the deterministic
11	 * {@link OwnerHousehold} householdId. Rejects with 409 via {@link DuplicateIdentityException} when
12	 * the new owner's whole {@link OwnerIdentityKey} ({@code <telephone>|<email>|<householdId>}) equals
13	 * an existing owner's — an exact duplicate.
14	 *
15	 * <p>Because the telephone is part of the key, members of the same household (same
16	 * {@code (lastName, postcode)}, hence the same computed householdId) with different telephones have
17	 * different keys and are both allowed — the household can hold several members. Such a soft match is
18	 * not rejected here; it is flagged instead by {@link AssignOwnerPossibleDuplicate}, and its
19	 * membership level is capped by the household ceiling.
20	 *
21	 * <p>Runs before {@link BuildOwner} so no owner is created on conflict, and resolves the householdId
22	 * the request would receive so its key matches the one assigned and returned afterwards.
23	 */
24	public class CheckUniqueOwnerIdentity {
25	
26	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
27	            throws DuplicateIdentityException {
28	        String householdId = OwnerHousehold.householdId(request);
29	        String identityKey = OwnerIdentityKey.of(request.getTelephone(), request.getEmail(), householdId);
30	        for (Owner existing : ownerRepository.findAll()) {
31	            if (Boolean.TRUE.equals(existing.getDeleted())) {
32	                continue; // a soft-deleted owner does not block a new registration
33	            }
34	            if (identityKey.equals(OwnerIdentityKey.of(existing))) {
35	                throw new DuplicateIdentityException(identityKey);
36	            }
37	        }
38	    }
39	}
