3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * Flags a new owner as a possible (soft) duplicate. A hard duplicate is already rejected earlier by
10	 * {@link CheckUniqueOwnerIdentity}; this step runs after {@link BuildOwner} and before
11	 * {@link SaveOwner}, so it compares against the owners already stored, not the one being created.
12	 * When an existing owner shares this owner's last name (case-insensitive) and postcode but has a
13	 * different telephone, {@code possibleDuplicate} is set true and {@code possibleDuplicateOf} to that
14	 * owner's id; otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf} null. An
15	 * owner that declared it shares a household ({@code sharesHousehold} true) is never flagged — a
16	 * declared household member is not a suspected duplicate. Both values are persisted so they are
17	 * returned unchanged on later reads of the owner.
18	 */
19	public class AssignOwnerPossibleDuplicate {
20	
21	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
22	        String lastName = owner.getLastName();
23	        String postcode = owner.getPostcode();
24	        String telephone = owner.getTelephone();
25	        owner.setPossibleDuplicate(false);
26	        owner.setPossibleDuplicateOf(null);
27	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
28	            return; // a declared household member is not a suspected duplicate
29	        }
30	        if (postcode == null) {
31	            return; // no postcode to share, so never a soft-match
32	        }
33	        for (Owner existing : ownerRepository.findAll()) {
34	            if (Boolean.TRUE.equals(existing.getDeleted())) {
35	                continue; // a soft-deleted owner is not a duplicate match
36	            }
37	            if (equalsIgnoreCase(lastName, existing.getLastName())
38	                    && postcode.equals(existing.getPostcode())
39	                    && !equals(telephone, existing.getTelephone())) {
40	                owner.setPossibleDuplicate(true);
41	                owner.setPossibleDuplicateOf(existing.getId());
42	                return;
43	            }
44	        }
45	    }
46	
47	    private static boolean equalsIgnoreCase(String a, String b) {
48	        return a == null ? b == null : a.equalsIgnoreCase(b);
49	    }
50	
51	    private static boolean equals(String a, String b) {
52	        return a == null ? b == null : a.equals(b);
53	    }
54	}
