10	/**
11	 * Rejects an email whose domain is on the disposable-domain blocklist. Email is optional, so an
12	 * absent or blank email is accepted. Runs after {@link NormalizeOwnerEmail}, which has already
13	 * lower-cased and syntactically validated the address, so the domain is the substring after the
14	 * final {@code @}. A blocklisted domain is rejected with 400 via
15	 * {@link DisposableEmailDomainException}.
16	 */
17	public class RejectDisposableEmailDomain {
18	
19	    private static final Set<String> BLOCKED_DOMAINS = Set.of(
20	            "mailinator.com",
21	            "tempmail.com",
22	            "guerrillamail.com");
23	
24	    public void service(@Val OwnerFieldsDto request) throws DisposableEmailDomainException {
25	        String email = request.getEmail();
26	        if (email == null || email.isBlank()) {
27	            return; // optional when absent
28	        }
29	        int at = email.lastIndexOf('@');
30	        if (at < 0) {
31	            return; // not a syntactically valid address; NormalizeOwnerEmail already guards this
32	        }
33	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
34	        if (BLOCKED_DOMAINS.contains(domain)) {
35	            throw new DisposableEmailDomainException(email);
36	        }
37	    }
38	}
