9	
10	/**
11	 * Email is optional. When absent (null or blank) this step leaves the request untouched. When
12	 * present it must be a syntactically valid address; the value is lower-cased in place (so the
13	 * mapper stores and later steps return the normalized form) and an invalid address is rejected
14	 * with 400 via {@link InvalidEmailException}.
15	 */
16	public class NormalizeOwnerEmail {
17	
18	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
19	
20	    public void service(@Val OwnerFieldsDto request) throws InvalidEmailException {
21	        String raw = request.getEmail();
22	        if (raw == null || raw.isBlank()) {
23	            return;
24	        }
25	        String email = raw.toLowerCase(Locale.ROOT);
26	        if (!EMAIL.matcher(email).matches()) {
27	            throw new InvalidEmailException(raw);
28	        }
29	        request.setEmail(email);
30	    }
31	}
