3	import java.util.LinkedHashMap;
4	import java.util.Map;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
9	
10	/**
11	 * Runs after {@link RequireOwnerFields} on {@code POST /api/owners}: normalizes the telephone into
12	 * E.164 form, replacing the field in place (so {@link BuildOwner} maps the normalized value).
13	 * <p>
14	 * Spaces, dashes and brackets are stripped. When the number carries a leading {@code '+'} the
15	 * country code is kept as given; otherwise country code {@code '+61'} is assumed and a single
16	 * leading {@code '0'} is dropped from the national digits. The result must have 8 to 15 digits
17	 * after the {@code '+'}.
18	 * <p>
19	 * The national-number length is then validated against the country code: {@code '+61'} requires
20	 * exactly 9 national digits and {@code '+1'} requires exactly 10. A number that cannot form a valid
21	 * E.164 string, or whose national number is the wrong length for its country code, is rejected with
22	 * 400 via {@link InvalidTelephoneException}.
23	 */
24	public class NormalizeOwnerTelephone {
25	
26	    /**
27	     * Country code (digits after the {@code '+'}) to the exact national-number length it requires.
28	     * Longest prefixes first so {@code '61'} is matched before {@code '1'}.
29	     */
30	    private static final Map<String, Integer> NATIONAL_LENGTHS = new LinkedHashMap<>();
31	
32	    static {
33	        NATIONAL_LENGTHS.put("61", 9);
34	        NATIONAL_LENGTHS.put("1", 10);
35	    }
36	
37	    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
38	        String raw = request.getTelephone();
39	        String stripped = raw == null ? "" : raw.replaceAll("[\\s\\-()]", "");
40	
41	        String digits;
42	        if (stripped.startsWith("+")) {
43	            digits = stripped.substring(1);
44	        }
45	        else {
46	            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
47	            digits = "61" + national;
48	        }
49	
50	        if (!digits.matches("\\d{8,15}")) {
51	            throw new InvalidTelephoneException(raw);
52	        }
53	
54	        for (Map.Entry<String, Integer> country : NATIONAL_LENGTHS.entrySet()) {
55	            String code = country.getKey();
56	            if (digits.startsWith(code)) {
57	                if (digits.length() - code.length() != country.getValue()) {
58	                    throw new InvalidTelephoneException(raw);
59	                }
60	                break;
61	            }
62	        }
63	
64	        request.setTelephone("+" + digits);
65	    }
66	}
